+namespace Microsoft.Integration.Shopify.Test;
+
+using Microsoft.Integration.Shopify;
+using Microsoft.Inventory.Item;
+using Microsoft.Finance.Currency;
+
+/// <summary>
+/// Codeunit Shpfy Create Item Currency Test (ID 139616).
+/// </summary>
+codeunit 139616 "Shpfy CreateItem Currency Test"
+{
+    Subtype = Test;
+    TestType = Uncategorized;
+    TestPermissions = Disabled;
+
+    var
+        LibraryAssert: Codeunit "Library Assert";
+        LibraryERM: Codeunit "Library - ERM";
+
+    [Test]
+    procedure UnitTestCreateItemWithShopCurrencyConvertsPrices()
+    var
+        Item: Record Item;
+        Shop: Record "Shpfy Shop";
+        ShopifyProduct: Record "Shpfy Product";
+        ShopifyVariant: Record "Shpfy Variant";
+        CurrencyExchangeRate: Record "Currency Exchange Rate";
+        Currency: Record Currency;
+        ProductInitTest: Codeunit "Shpfy Product Init Test";
+        InitializeTest: Codeunit "Shpfy Initialize Test";
+        ExpectedUnitCost: Decimal;
+        ExpectedUnitPrice: Decimal;
+        ExchangeRate: Decimal;
+        VariantPrice: Decimal;
+        VariantUnitCost: Decimal;
+    begin
+        // [SCENARIO] When creating an Item from a Shopify Product and the Shop has a Currency Code set,
+        // the Unit Cost and Unit Price should be converted from FCY to LCY using exchange rates.
+
+        // [GIVEN] A Shop with a Currency Code set (e.g., DKK)
+        Shop := InitializeTest.CreateShop();
+        Shop."SKU Mapping" := "Shpfy SKU Mapping"::"Item No.";
+
+        LibraryERM.CreateCurrency(Currency);
+        ExchangeRate := 100 / 685; // e.g., 1 LCY = 6.85 FCY
+        LibraryERM.CreateExchangeRate(Currency.Code, WorkDate(), ExchangeRate, ExchangeRate);
+
+        Shop."Currency Code" := Currency.Code;
+        Shop.Modify();
+
+        // [GIVEN] A Shopify variant record with specific prices
+        ShopifyVariant := ProductInitTest.CreateStandardProduct(Shop);
+
+        // Set known price values on the variant for predictable assertion
+        VariantPrice := 5000;
+        VariantUnitCost := 2500;
+        ShopifyVariant.Price := VariantPrice;
+        ShopifyVariant."Unit Cost" := VariantUnitCost;
+        ShopifyVariant.Modify();
+        ShopifyVariant.SetRecFilter();
+
+        // [GIVEN] Expected converted values
+        ExpectedUnitCost := Round(CurrencyExchangeRate.ExchangeAmtFCYToLCY(WorkDate(), Currency.Code, VariantUnitCost, CurrencyExchangeRate.ExchangeRate(WorkDate(), Currency.Code)));
+        ExpectedUnitPrice := Round(CurrencyExchangeRate.ExchangeAmtFCYToLCY(WorkDate(), Currency.Code, VariantPrice, CurrencyExchangeRate.ExchangeRate(WorkDate(), Currency.Code)));
+
+        // [WHEN] Executing the codeunit "Shpfy Create Item" with the "Shpfy Variant" Record.
+        Codeunit.Run(Codeunit::"Shpfy Create Item", ShopifyVariant);
+
+        // [THEN] The Item is created
+        LibraryAssert.IsFalse(IsNullGuid(ShopifyVariant."Item SystemId"), 'Item SystemId <> NullGuid');
+        LibraryAssert.IsTrue(Item.GetBySystemId(ShopifyVariant."Item SystemId"), 'Get Item');
+
+        // [THEN] The Item Unit Cost and Unit Price should be converted from FCY to LCY, not the raw Shopify values
+        LibraryAssert.AreNotEqual(VariantUnitCost, Item."Unit Cost", 'Unit Cost should not equal raw Shopify value when currency is set');
+        LibraryAssert.AreNotEqual(VariantPrice, Item."Unit Price", 'Unit Price should not equal raw Shopify value when currency is set');
+        LibraryAssert.AreEqual(ExpectedUnitCost, Item."Unit Cost", 'Unit Cost should be converted from FCY to LCY');
+        LibraryAssert.AreEqual(ExpectedUnitPrice, Item."Unit Price", 'Unit Price should be converted from FCY to LCY');
+    end;
+}
